class DualLogger:
    """Intercepts terminal output and writes it to both the console and a log file."""
    def __init__(self, filepath):
        self.terminal = sys.stdout
        self.log = open(filepath, "a", encoding="utf-8")

    def write(self, message):
        # MOBILESPY_2_5_LIVE_LOG_FLUSH_V1
        # Flush BOTH destinations immediately. This matters when stdout is
        # piped through tools such as `tee`, where Python otherwise block-buffers
        # the rich print()-based agent logs while logging/stderr stays live.
        self.terminal.write(message)
        self.terminal.flush()
        self.log.write(message)
        self.log.flush()

    def flush(self):
        self.terminal.flush()
        self.log.flush()

