# Never commit live credentials to this crawler: screenshots can contain private
# account data and the source is routinely copied into patch/review artifacts.
# Multiple OpenAI keys may be supplied as a comma-separated rotation list.
# Environment values take precedence so credentials never need to be written
# into this file.  The final tuple keeps backwards compatibility for operators
# who intentionally populate the local list on an isolated machine.
_DIRECT_API_KEYS = [""]
API_KEYS = []
for _raw_keys in (
    os.getenv("MOBILESPY_OPENAI_API_KEYS", ""),
    os.getenv("OPENAI_API_KEYS", ""),
    os.getenv("OPENAI_API_KEY", ""),
    ",".join(_DIRECT_API_KEYS),
):
    for _candidate_key in _raw_keys.split(","):
        _candidate_key = _candidate_key.strip()
        if _candidate_key and _candidate_key not in API_KEYS:
            API_KEYS.append(_candidate_key)
PIXABAY_API_KEY = ""


class MobileSpyAIUnavailable(RuntimeError):
    """Terminal provider failure that must checkpoint and pause the crawler."""


class MobileSpyDeviceUnavailable(RuntimeError):
    """Android system failure that must checkpoint instead of looping recovery."""


def _build_openai_response_input(prompt, image=None, images=None, detail=None):
    """Build one Responses API user item while preserving image order."""
    content = [{"type": "input_text", "text": str(prompt)}]
    ordered_images = []
    if image is not None:
        ordered_images.append(image)
    if images:
        ordered_images.extend(img for img in images if img is not None)
    image_detail = detail or OPENAI_IMAGE_DETAIL
    for img in ordered_images:
        if not isinstance(img, (bytes, bytearray, memoryview)):
            raise TypeError("MobileSpy image inputs must be PNG bytes")
        encoded = base64.b64encode(bytes(img)).decode("ascii")
        content.append({
            "type": "input_image",
            "image_url": f"data:image/png;base64,{encoded}",
            "detail": image_detail,
        })
    return [{"role": "user", "content": content}]


