if __name__ == "__main__":
    agent = UniversalMobileSpy()
    try:
        asyncio.run(agent.run())
    except KeyboardInterrupt:
        print("\n\n🛑 SCRIPT INTERRUPTED BY USER (Ctrl+C)")
        print("💾 Forcing a final save of the session manifest and memory...")
    except MobileSpyAIUnavailable as e:
        print(f"\n\n⏸️ MOBILESPY PAUSED: AI provider unavailable: {e}")
        print("💾 Checkpointing the graph and capture trail before exit...")
    except MobileSpyDeviceUnavailable as e:
        print(f"\n\n⏸️ MOBILESPY PAUSED: device unavailable: {e}")
        print("💾 Checkpointing the graph and capture trail before exit...")
    except Exception as e:
        print(f"\n\n🛑 SCRIPT CRASHED: {e}")
        traceback.print_exc()
        print("💾 Forcing a final save of the session manifest and memory...")
    finally:
        # Force a save of everything we currently have in session_data
        try:
            agent.memory.save_memory()
            agent.session_data["app_understanding"] = agent.memory.app_understanding
            agent.session_data["exploration_progress"] = agent.memory.app_map.get_exploration_progress()
            agent.session_data["screen_knowledge"] = agent.memory.screen_kb.get_summary()
            agent.session_data["flow_summary"] = agent.memory.flow_tracker.get_flow_summary()
            agent.session_data["blocked_paths"] = agent.memory.blocked_paths.get_all()
            agent.session_data["safety_summary"] = agent.safety.get_summary()
            agent.session_data["discovered_templates"] = agent.memory.discovered_templates
            agent.session_data["page_fingerprint_registry"] = agent.memory.page_fingerprint_registry
            if getattr(agent, "control_plane", None):
                agent.control_plane.state_engine.checkpoint(reason="emergency_save")
                agent.session_data["state_intelligence"] = agent.control_plane.state_engine.report()
                agent.session_data["watchdog"] = agent.control_plane.watchdog.summary()
                agent._normalize_manifest_contract()
                agent.control_plane.write_unattended_audit(
                    agent.data_dir, agent.session_data,
                    repair_report=agent.session_data.get("unattended_repair"),
                )
                agent.control_plane.write_report(agent.data_dir, agent.session_data)

            # Ensure bugs are preserved during emergency saves
            if "app_bugs" not in agent.session_data:
                agent.session_data["app_bugs"] = []

            agent._force_save_manifest()

            print(f"✅ Emergency save complete. Check {agent.data_dir}/session_manifest.json")
        except Exception as save_err:
            print(f"⚠️ Emergency save failed: {save_err}")
